window.TTS_DATA=window.TTS_DATA||{};window.TTS_DATA[6]=[{"t": "h", "l": 0, "s": "Лекц 6. Хоёр талаас тэжээгдэх ба цагираг сүлжээ", "h": "<b>Лекц 6. Хоёр талаас тэжээгдэх ба цагираг сүлжээ</b>"}, {"t": "p", "s": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг", "h": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг"}, {"t": "p", "s": "Лекцийн зорилго. Хаалттай (цагираг ба хоёр талаас тэжээгдэх) сүлжээний чадлын хуваарилалтыг тооцох аргууд: эсэргүүцлийн моментын дүрэм, чадлын хуваагдлын цэг, эх үүсвэрийн хүчдэл тэгш бус үеийн тэгшитгэх урсгал, нэгэн төрлийн бус сүлжээний байгалийн ба эдийн засгийн хуваарилалт, ослын (n−1) горим, мөн хаалттай сүлжээний тооцоог зангилааны тэгшитгэл ба Zbus матрицаар хийх.", "h": "<b>Лекцийн зорилго. </b>Хаалттай (цагираг ба хоёр талаас тэжээгдэх) сүлжээний чадлын хуваарилалтыг тооцох аргууд: эсэргүүцлийн моментын дүрэм, чадлын хуваагдлын цэг, эх үүсвэрийн хүчдэл тэгш бус үеийн тэгшитгэх урсгал, нэгэн төрлийн бус сүлжээний байгалийн ба эдийн засгийн хуваарилалт, ослын (n−1) горим, мөн хаалттай сүлжээний тооцоог зангилааны тэгшитгэл ба <b>Z</b><sub>bus</sub> матрицаар хийх.", "x": "obj"}, {"t": "p", "s": "Түлхүүр үг: цагираг сүлжээ, хоёр талаас тэжээгдэх шугам, моментын дүрэм, чадлын хуваагдлын цэг, тэгшитгэх урсгал, нэгэн төрлийн сүлжээ, байгалийн хуваарилалт, эдийн засгийн хуваарилалт, уртааш-хөндлөн тохируулга, Кроны бууруулалт, n−1 шалгуур.", "h": "<b>Түлхүүр үг: </b>цагираг сүлжээ, хоёр талаас тэжээгдэх шугам, моментын дүрэм, чадлын хуваагдлын цэг, тэгшитгэх урсгал, нэгэн төрлийн сүлжээ, байгалийн хуваарилалт, эдийн засгийн хуваарилалт, уртааш-хөндлөн тохируулга, Кроны бууруулалт, n−1 шалгуур.", "x": "obj"}, {"t": "h", "l": 1, "s": "1. Хаалттай сүлжээний төрөл ба давуу тал", "h": "<b>1. Хаалттай сүлжээний төрөл ба давуу тал</b>"}, {"t": "p", "s": "Хэрэглэгч бүр хоёр ба түүнээс олон замаар тэжээгдэх сүлжээг хаалттай сүлжээ гэнэ. Үндсэн хэлбэрүүд: (1) хоёр талаас тэжээгдэх шугам — хоёр эх үүсвэр (цахилгаан станц эсвэл дэд станцын шин) хооронд хэд хэдэн ачааллыг дамжуулан тэжээх; (2) цагираг сүлжээ — нэг эх үүсвэрээс гарч буцаж ирэх битүү хүрээ; энэ нь хоёр үзүүрийн хүчдэл тэнцүү хоёр талаас тэжээгдэх шугамын тусгай тохиолдол; (3) нийлмэл торон сүлжээ — олон контуртай, олон эх үүсвэртэй систем үүсгэгч сүлжээ (220 кВ ба түүнээс дээш).", "h": "Хэрэглэгч бүр хоёр ба түүнээс олон замаар тэжээгдэх сүлжээг <b>хаалттай </b>сүлжээ гэнэ. Үндсэн хэлбэрүүд: (1) <b>хоёр талаас тэжээгдэх шугам </b>— хоёр эх үүсвэр (цахилгаан станц эсвэл дэд станцын шин) хооронд хэд хэдэн ачааллыг дамжуулан тэжээх; (2) <b>цагираг</b> сүлжээ — нэг эх үүсвэрээс гарч буцаж ирэх битүү хүрээ; энэ нь хоёр үзүүрийн хүчдэл тэнцүү хоёр талаас тэжээгдэх шугамын тусгай тохиолдол; (3) <b>нийлмэл торон </b>сүлжээ — олон контуртай, олон эх үүсвэртэй систем үүсгэгч сүлжээ (220 кВ ба түүнээс дээш)."}, {"t": "p", "s": "Хаалттай сүлжээний давуу тал: тэжээлийн найдвартай байдал (нэг элемент гэмтэхэд хэрэглэгч тасрахгүй — n−1 шалгуур), хүчдэлийн алдагдал ба чадлын алдагдал бага, эх үүсвэрүүдийн чадлыг хамтран ашиглах боломж. Сул тал: богино залгааны гүйдэл их, релейн хамгаалалт нийлмэл, чадлын урсгалыг удирдах хэцүү, горимын тооцоо радиаль сүлжээнийхээс нийлмэл — чадал аль замаар хэдий хэмжээгээр гүйхийг урьдчилан мэдэхгүй, сүлжээний параметрээр тодорхойлогдоно.", "h": "Хаалттай сүлжээний давуу тал: тэжээлийн найдвартай байдал (нэг элемент гэмтэхэд хэрэглэгч тасрахгүй — n−1 шалгуур), хүчдэлийн алдагдал ба чадлын алдагдал бага, эх үүсвэрүүдийн чадлыг хамтран ашиглах боломж. Сул тал: богино залгааны гүйдэл их, релейн хамгаалалт нийлмэл, чадлын урсгалыг удирдах хэцүү, горимын тооцоо радиаль сүлжээнийхээс нийлмэл — чадал аль замаар хэдий хэмжээгээр гүйхийг урьдчилан мэдэхгүй, сүлжээний параметрээр тодорхойлогдоно."}, {"t": "p", "s": "Монголын төвийн эрчим хүчний системд 220 кВ-ын Улаанбаатар–Дархан–Эрдэнэт– Улаанбаатар контур, Улаанбаатар хотын 110 кВ-ын цагираг сүлжээ (ДЦС-2, 3, 4-ийг холбосон) хаалттай сүлжээний жишээ болно.", "h": "Монголын төвийн эрчим хүчний системд 220 кВ-ын Улаанбаатар–Дархан–Эрдэнэт– Улаанбаатар контур, Улаанбаатар хотын 110 кВ-ын цагираг сүлжээ (ДЦС-2, 3, 4-ийг холбосон) хаалттай сүлжээний жишээ болно."}, {"t": "h", "l": 1, "s": "2. Хоёр талаас тэжээгдэх шугам — тэнцүү хүчдэлтэй", "h": "<b>2. Хоёр талаас тэжээгдэх шугам — тэнцүү хүчдэлтэй</b>"}, {"t": "p", "s": "A(U̇ A) 1 2 B (U̇ B)", "h": "A<sub>(U</sub><sup>̇</sup> <sub>A)</sub> <sub>1</sub> <sub>2</sub> <sub>B</sub> <sub>(U</sub><sup>̇</sup> <sub>B)</sub>"}, {"t": "p", "s": "→ Ṡ_A Ṡ_B ←", "h": "→ <sub>Ṡ_A</sub> <sub>Ṡ_B</sub> <sub>←</sub>"}, {"t": "p", "s": "Z_A1 Z_12 Z_2B", "h": "Z<sub>_A1</sub> <sub>Z_12</sub> <sub>Z_2B</sub>"}, {"t": "p", "s": "Ṡ₁ Ṡ₂", "h": "Ṡ<sub>₁</sub> <sub>Ṡ₂</sub>"}, {"t": "cap", "s": "Зураг 6.1. Хоёр талаас тэжээгдэх шугам", "h": "Зураг 6.1. Хоёр талаас тэжээгдэх шугам"}, {"t": "p", "s": "Эхний ойролцоололд алдагдлыг тооцохгүй, бүх зангилааны хүчдэлийг нэрлэсэн Uнтэй тэнцүү гэж үзье. A ба B үзүүрийн хүчдэл тэнцүү (U̇ A = U̇ B) бол A-гаас B хүртэлх хүчдэлийн уналтын нийлбэр тэг байна (Кирхгофын II хууль). Салааны гүйдлийг чадлаар илэрхийлж İ = Ṡ*/(√3Uн) гэж орлуулбал Aүзүүрээс гарах чадал:", "h": "Эхний ойролцоололд алдагдлыг тооцохгүй, бүх зангилааны хүчдэлийг нэрлэсэн U<sub>н</sub>тэй тэнцүү гэж үзье. A ба B үзүүрийн хүчдэл тэнцүү (U̇ <sub>A</sub> = U̇ <sub>B</sub>) бол A-гаас B хүртэлх хүчдэлийн уналтын нийлбэр тэг байна (Кирхгофын II хууль). Салааны гүйдлийг чадлаар илэрхийлж İ = Ṡ*/(√3U<sub>н</sub>) гэж орлуулбал Aүзүүрээс гарах чадал:"}, {"t": "eq", "s": "ṠA = Σi Ṡi·Z*iB / Z*AB ; ṠB = Σi Ṡi·Z*iA / Z*AB (6.1)", "h": "Ṡ<sub>A</sub> = Σ<sub>i</sub> Ṡ<sub>i</sub>·Z*<sub>iB</sub> / Z*<sub>AB</sub> ; Ṡ<sub>B</sub> = Σ<sub>i</sub> Ṡ<sub>i</sub>·Z*<sub>iA</sub> / Z*<sub>AB</sub> (6.1)", "n": "6.1", "img": "data:image/png;base64,", "iw": 488}, {"t": "p", "s": "Энд ZiB — i ачааллаас эсрэг талын (B) эх үүсвэр хүртэлх эсэргүүцэл, ZAB — шугамын нийт эсэргүүцэл, * — комплекс хосмог. Энэ томьёо механикийн хоёр тулгууртай дамнуургын тулгуурын урвалын томьёотой адил тул эсэргүүцлийн моментын дүрэм гэж нэрлэдэг: ачаалал аль эх үүсвэрт ойр байна, түүнээс илүү тэжээгдэнэ. Шалгалт: ṠA + ṠB = ΣṠi.", "h": "Энд Z<sub>iB</sub> — i ачааллаас эсрэг талын (B) эх үүсвэр хүртэлх эсэргүүцэл, Z<sub>AB</sub> — шугамын нийт эсэргүүцэл, * — комплекс хосмог. Энэ томьёо механикийн хоёр тулгууртай дамнуургын тулгуурын урвалын томьёотой адил тул <b>эсэргүүцлийн моментын дүрэм </b>гэж нэрлэдэг: ачаалал аль эх үүсвэрт ойр байна, түүнээс илүү тэжээгдэнэ. Шалгалт: Ṡ<sub>A</sub> + Ṡ<sub>B</sub> = ΣṠ<sub>i</sub>."}, {"t": "p", "s": "Дунд хэсгийн салааны чадлыг Кирхгофын I хуулиар олно: Ṡ12 = ṠA − Ṡ1. Хэрэв Ṡ12ийн бодит хэсэг эерэг бол бодит чадал 1-ээс 2 руу, сөрөг бол эсрэг чиглэлд урсана.", "h": "Дунд хэсгийн салааны чадлыг Кирхгофын I хуулиар олно: Ṡ<sub>12</sub> = Ṡ<sub>A</sub> − Ṡ<sub>1</sub>. Хэрэв Ṡ<sub>12</sub>ийн бодит хэсэг эерэг бол бодит чадал 1-ээс 2 руу, сөрөг бол эсрэг чиглэлд урсана."}, {"t": "h", "l": 1, "s": "3. Нэгэн төрлийн сүлжээ", "h": "<b>3. Нэгэн төрлийн сүлжээ</b>"}, {"t": "p", "s": "Бүх салаа нь ижил X/R харьцаатай (ижил огтлолын дамжуулагч, ижил тулгуур) сүлжээг нэгэн төрлийн гэнэ. Тэгвэл Zij = z0Lij бөгөөд (6.1)-д z*0 хураагдаж, чадлын хуваарилалт зөвхөн уртаар тодорхойлогдоно:", "h": "Бүх салаа нь ижил X/R харьцаатай (ижил огтлолын дамжуулагч, ижил тулгуур) сүлжээг <b>нэгэн төрлийн </b>гэнэ. Тэгвэл Z<sub>ij</sub> = z<sub>0</sub>L<sub>ij</sub> бөгөөд (6.1)-д z*<sub>0</sub> хураагдаж, чадлын хуваарилалт зөвхөн <b>уртаар </b>тодорхойлогдоно:"}, {"t": "eq", "s": "PA = ΣPiLiB/LAB ; QA = ΣQiLiB/LAB (6.2)", "h": "P<sub>A</sub> = ΣP<sub>i</sub>L<sub>iB</sub>/L<sub>AB</sub> ; Q<sub>A</sub> = ΣQ<sub>i</sub>L<sub>iB</sub>/L<sub>AB</sub> (6.2)", "n": "6.2", "img": "data:image/png;base64,", "iw": 457}, {"t": "p", "s": "Бодит ба хуурмаг чадлыг тусад нь бодит тоогоор тооцож болох тул гар тооцоо маш хялбар болно. Хотын 110 кВ цагираг сүлжээ ихэвчлэн нэг огтлолын дамжуулагчаар баригддаг тул (6.2)-ыг өргөн хэрэглэдэг.", "h": "Бодит ба хуурмаг чадлыг тусад нь бодит тоогоор тооцож болох тул гар тооцоо маш хялбар болно. Хотын 110 кВ цагираг сүлжээ ихэвчлэн нэг огтлолын дамжуулагчаар баригддаг тул (6.2)-ыг өргөн хэрэглэдэг."}, {"t": "h", "l": 1, "s": "4. Чадлын хуваагдлын цэг ба нарийвчилсан тооцоо", "h": "<b>4. Чадлын хуваагдлын цэг ба нарийвчилсан тооцоо</b>"}, {"t": "p", "s": "Хоёр тал руугаа тэжээгдэж буй (хоёр талаас чадал орж ирж буй) зангилааг чадлын хуваагдлын цэг гэнэ; схемд ▼ тэмдгээр тэмдэглэнэ. Бодит ба хуурмаг чадлын хуваагдлын цэг өөр өөр зангилаанд байж болно (▼ — бодит, ▽ — хуурмаг). Нэгэн төрлийн сүлжээнд хуваагдлын цэг дээр хүчдэл хамгийн бага байна.", "h": "Хоёр тал руугаа тэжээгдэж буй (хоёр талаас чадал орж ирж буй) зангилааг <b>чадлын</b> <b>хуваагдлын цэг </b>гэнэ; схемд ▼ тэмдгээр тэмдэглэнэ. Бодит ба хуурмаг чадлын хуваагдлын цэг өөр өөр зангилаанд байж болно (▼ — бодит, ▽ — хуурмаг). Нэгэн төрлийн сүлжээнд хуваагдлын цэг дээр хүчдэл хамгийн бага байна."}, {"t": "p", "s": "Нарийвчилсан (алдагдлыг тооцсон) тооцооны алгоритм:", "h": "Нарийвчилсан (алдагдлыг тооцсон) тооцооны алгоритм:"}, {"t": "p", "s": "1. Алдагдалгүйгээр (6.1)-ээр чадлын урьдчилсан хуваарилалтыг олох.", "h": "1. Алдагдалгүйгээр (6.1)-ээр чадлын урьдчилсан хуваарилалтыг олох."}, {"t": "p", "s": "2. Чадлын хуваагдлын цэгээр сүлжээг хоёр радиаль сүлжээ болгон «задлах»: хуваагдлын цэгийн ачааллыг хоёр талаас ирэх чадлаар хуваана.", "h": "2. Чадлын хуваагдлын цэгээр сүлжээг <b>хоёр радиаль </b>сүлжээ болгон «задлах»: хуваагдлын цэгийн ачааллыг хоёр талаас ирэх чадлаар хуваана."}, {"t": "p", "s": "3. Радиаль хэсэг бүрийг лекц 5-ын хоёр үе шаттай аргаар тооцох (алдагдал, хүчдэл).", "h": "3. Радиаль хэсэг бүрийг лекц 5-ын хоёр үе шаттай аргаар тооцох (алдагдал, хүчдэл)."}, {"t": "p", "s": "4. Хуваагдлын цэгийн хүчдэлийг хоёр талаас тооцсон утгууд ойролцоо гарах ёстой — шалгалт.", "h": "4. Хуваагдлын цэгийн хүчдэлийг хоёр талаас тооцсон утгууд ойролцоо гарах ёстой — шалгалт."}, {"t": "p", "s": "Энэ аргын алдаа нь эхний алхамд алдагдлыг тооцоогүйгээс үүдэх бөгөөд 110 кВ сүлжээнд 1–3 %. Нарийвчилсан шийдлийг зангилааны тэгшитгэлээр (9-р бүлэг) олно.", "h": "Энэ аргын алдаа нь эхний алхамд алдагдлыг тооцоогүйгээс үүдэх бөгөөд 110 кВ сүлжээнд 1–3 %. Нарийвчилсан шийдлийг зангилааны тэгшитгэлээр (9-р бүлэг) олно."}, {"t": "h", "l": 1, "s": "5. Жишээ: 110 кВ цагираг сүлжээ", "h": "<b>5. Жишээ: 110 кВ цагираг сүлжээ</b>"}, {"t": "p", "s": "Жишээ 6.1. 110 кВ цагираг сүлжээ A–1–2–A, бүх шугам АС-240 (z0 = 0.12 + j0.405 Ом/ км). Урт: A–1 30 км, 1–2 20 км, 2–A 40 км. Тооцооны ачаалал: Ṡ1 = 30 + j18, Ṡ2 = 25 + j15 МВА. Тэжээх шин UA = 118 кВ. Чадлын хуваарилалт, алдагдал, хүчдэлийг ол.", "h": "<b>Жишээ 6.1. </b>110 кВ цагираг сүлжээ A–1–2–A, бүх шугам АС-240 (z<sub>0</sub> = 0.12 + j0.405 Ом/ км). Урт: A–1 30 км, 1–2 20 км, 2–A 40 км. Тооцооны ачаалал: Ṡ<sub>1</sub> = 30 + j18, Ṡ<sub>2</sub> = 25 + j15 МВА. Тэжээх шин U<sub>A</sub> = 118 кВ. Чадлын хуваарилалт, алдагдал, хүчдэлийг ол.", "x": "ex"}, {"t": "p", "s": "1. Эсэргүүцэл: ZA1 = 3.6 + j12.15; Z12 = 2.4 + j8.1; Z2A = 4.8 + j16.2; ZΣ = 10.8 + j36.45 Ом.", "h": "<b>1. Эсэргүүцэл: </b>Z<sub>A1</sub> = 3.6 + j12.15; Z<sub>12</sub> = 2.4 + j8.1; Z<sub>2A</sub> = 4.8 + j16.2; Z<sub>Σ</sub> = 10.8 + j36.45 Ом.", "x": "ex"}, {"t": "p", "s": "2. Цагирагийг A цэгээр «задалж» хоёр талаас тэжээгдэх шугам A–1–2–A′ гэж үзнэ. Сүлжээ нэгэн төрлийн тул (6.2):", "h": "<b>2. Цагирагийг A цэгээр «задалж» </b>хоёр талаас тэжээгдэх шугам A–1–2–A′ гэж үзнэ. Сүлжээ нэгэн төрлийн тул (6.2):", "x": "ex"}, {"t": "p", "s": "ṠA1 = [(30 + j18)·60 + (25 + j15)·40]/90 = 31.11 + j18.67 МВА; ṠA2 = [(25 + j15)·50 + (30 + j18)·30]/90 = 23.89 + j14.33 МВА.", "h": "Ṡ<sub>A1</sub> = [(30 + j18)·60 + (25 + j15)·40]/90 = <b>31.11 + j18.67 </b>МВА; Ṡ<sub>A2</sub> = [(25 + j15)·50 + (30 + j18)·30]/90 = <b>23.89 + j14.33 </b>МВА.", "x": "ex"}, {"t": "p", "s": "Шалгалт: 31.11 + 23.89 = 55 = P1 + P2 ✓. Дунд салаа: Ṡ12 = 31.11 − 30 + j(18.67 − 18) = 1.11 + j0.67 МВА — 1-ээс 2 руу. Иймд 2-р зангилаа бодит ба хуурмаг чадлын хуваагдлын цэг.", "h": "Шалгалт: 31.11 + 23.89 = 55 = P<sub>1</sub> + P<sub>2</sub> ✓. Дунд салаа: Ṡ<sub>12</sub> = 31.11 − 30 + j(18.67 − 18) = 1.11 + j0.67 МВА — 1-ээс 2 руу. Иймд <b>2-р зангилаа </b>бодит ба хуурмаг чадлын хуваагдлын цэг.", "x": "ex"}, {"t": "p", "s": "3. Задалсан хоёр радиаль сүлжээ: (а) A–1–2′ (2′-ын ачаалал 1.11 + j0.67), (б) A′–2″ (2″ын ачаалал 23.89 + j14.33).", "h": "<b>3. Задалсан хоёр радиаль сүлжээ: </b>(а) A–1–2′ (2′-ын ачаалал 1.11 + j0.67), (б) A′–2″ (2″ын ачаалал 23.89 + j14.33).", "x": "ex"}, {"t": "p", "s": "4. Алдагдал (Uн = 110 кВ): ΔṠ12 = (1.11² + 0.67²)/110²·(2.4 + j8.1) ≈ 0.0003 + j0.001; A–1 салааны төгсгөл 31.11 + j18.67, ΔṠA1 = 0.392 + j1.322 → эхлэл 31.50 + j19.99 МВА. 2–A салаа: ΔṠ2A = 0.308 + j1.039 → эхлэл 24.20 + j15.37 МВА. Нийт алдагдал 0.70 + j2.36 МВА.", "h": "<b>4. Алдагдал </b>(U<sub>н</sub> = 110 кВ): ΔṠ<sub>12</sub> = (1.11² + 0.67²)/110²·(2.4 + j8.1) ≈ 0.0003 + j0.001; A–1 салааны төгсгөл 31.11 + j18.67, ΔṠ<sub>A1</sub> = 0.392 + j1.322 → эхлэл 31.50 + j19.99 МВА. 2–A салаа: ΔṠ<sub>2A</sub> = 0.308 + j1.039 → эхлэл 24.20 + j15.37 МВА. Нийт алдагдал 0.70 + j2.36 МВА.", "x": "ex"}, {"t": "p", "s": "5. Хүчдэл: ΔUA1 = (31.50·3.6 + 19.99·12.15)/118 = 3.02 кВ, δU = 2.63 кВ → U1 = 115.01 кВ. 1-ээс 2: U2 = 114.94 кВ. Нөгөө талаас A′–2: ΔU = 3.09, δU = 2.70 → U2 = 114.94 кВ. Хоёр талаас тооцсон U2 давхцаж байна ✓.", "h": "<b>5. Хүчдэл: </b>ΔU<sub>A1</sub> = (31.50·3.6 + 19.99·12.15)/118 = 3.02 кВ, δU = 2.63 кВ → U<sub>1</sub> = 115.01 кВ. 1-ээс 2: U<sub>2</sub> = 114.94 кВ. Нөгөө талаас A′–2: ΔU = 3.09, δU = 2.70 → U<sub>2</sub> = 114.94 кВ. Хоёр талаас тооцсон U<sub>2</sub> давхцаж байна ✓.", "x": "ex"}, {"t": "p", "s": "6. Нарийвчилсан шийдэлтэй харьцуулах (9-р бүлгийн Zbus арга): U1 = 115.02, U2 = 114.95 кВ, алдагдал 0.64 + j2.16 МВА. Хүчдэлийн алдаа 0.01 кВ; алдагдлыг нэрлэсэн 110 кВ-оор тооцсон тул 9 %-иар илүү гарсан (бодит хүчдэл ≈115 кВ: (110/115)² = 0.915).", "h": "<b>6. Нарийвчилсан шийдэлтэй харьцуулах </b>(9-р бүлгийн <b>Z</b><sub>bus</sub> арга): U<sub>1</sub> = 115.02, U<sub>2</sub> = 114.95 кВ, алдагдал 0.64 + j2.16 МВА. Хүчдэлийн алдаа 0.01 кВ; алдагдлыг нэрлэсэн 110 кВ-оор тооцсон тул 9 %-иар илүү гарсан (бодит хүчдэл ≈115 кВ: (110/115)² = 0.915).", "x": "ex"}, {"t": "p", "s": "Жишээ 6.2. Бодит ба хуурмаг чадлын хуваагдлын цэг ялгаатай. 10 кВ нэгэн төрлийн кабель цагираг A–1–2–3–A (r0 = 0.32, x0 = 0.35 Ом/км): урт 2; 1.5; 1; 2.5 км (нийт 7 км). Ачаалал Ṡ1 = 1.2 + j1.5, Ṡ2 = 0.6 + j0.2, Ṡ3 = 0.8 + j0.6 МВА.", "h": "<b>Жишээ 6.2. Бодит ба хуурмаг чадлын хуваагдлын цэг ялгаатай. </b>10 кВ нэгэн төрлийн кабель цагираг A–1–2–3–A (r<sub>0</sub> = 0.32, x<sub>0</sub> = 0.35 Ом/км): урт 2; 1.5; 1; 2.5 км (нийт 7 км). Ачаалал Ṡ<sub>1</sub> = 1.2 + j1.5, Ṡ<sub>2</sub> = 0.6 + j0.2, Ṡ<sub>3</sub> = 0.8 + j0.6 МВА.", "x": "ex"}, {"t": "p", "s": "(6.2): PA = (1.2·5 + 0.6·3.5 + 0.8·2.5)/7 = 1.443 МВт; QA = (1.5·5 + 0.2·3.5 + 0.6·2.5)/7 = 1.386 Мвар. Салааны урсгал: A–1: 1.443 + j1.386; 1–2: 0.243 − j0.114; 2–3: −0.357 − j0.314; 3–A: −1.157 − j0.914 МВА.", "h": "(6.2): P<sub>A</sub> = (1.2·5 + 0.6·3.5 + 0.8·2.5)/7 = 1.443 МВт; Q<sub>A</sub> = (1.5·5 + 0.2·3.5 + 0.6·2.5)/7 = 1.386 Мвар. Салааны урсгал: A–1: 1.443 + j1.386; 1–2: 0.243 − j0.114; 2–3: −0.357 − j0.314; 3–A: −1.157 − j0.914 МВА.", "x": "ex"}, {"t": "p", "s": "1–2 салаанд бодит чадал 1 → 2, харин хуурмаг чадал 2 → 1 чиглэлтэй. Иймд бодит чадлын хуваагдлын цэг — 2 (▼), хуурмаг чадлын — 1 (▽). Ийм үед хүчдэлийн хамгийн бага цэгийг хоёр цэгт хоёуланд нь шалгана: ΔUA1 = (1.443·0.64 + 1.386·0.70)/10 = 0.189 кВ; 2-р зангилаа хүртэл A талаас 0.195 кВ, B талаас (3-аар) 0.195 кВ ✓. Хамгийн их хүчдэлийн алдагдал 2-р зангилаанд 1.95 %. Алдагдал ΔP = ΣSj²r0Lj/Uн² = 44 кВт.", "h": "1–2 салаанд бодит чадал 1 → 2, харин хуурмаг чадал 2 → 1 чиглэлтэй. Иймд <b>бодит</b> <b>чадлын хуваагдлын цэг — 2 </b>(▼), <b>хуурмаг чадлын — 1 </b>(▽). Ийм үед хүчдэлийн хамгийн бага цэгийг хоёр цэгт хоёуланд нь шалгана: ΔU<sub>A1</sub> = (1.443·0.64 + 1.386·0.70)/10 = 0.189 кВ; 2-р зангилаа хүртэл A талаас 0.195 кВ, B талаас (3-аар) 0.195 кВ ✓. Хамгийн их хүчдэлийн алдагдал 2-р зангилаанд 1.95 %. Алдагдал ΔP = ΣS<sub>j</sub>²r<sub>0</sub>L<sub>j</sub>/U<sub>н</sub>² = 44 кВт.", "x": "ex"}, {"t": "h", "l": 1, "s": "6. Эх үүсвэрийн хүчдэл тэгш бус — тэгшитгэх урсгал", "h": "<b>6. Эх үүсвэрийн хүчдэл тэгш бус — тэгшитгэх урсгал</b>"}, {"t": "p", "s": "U̇ A ≠ U̇ B бол (6.1)-д нэмэлт гишүүн гарна. Суперпозицийн зарчмаар чадлыг хоёр бүрэлдэхүүний нийлбэрээр илэрхийлнэ: (1) хүчдэл тэнцүү үеийн ачааллын чадал (6.1); (2) ачаалалгүй үед хүчдэлийн зөрүүгээр үүсэх тэгшитгэх урсгал (уравнительная мощность):", "h": "U̇ <sub>A</sub> ≠ U̇ <sub>B</sub> бол (6.1)-д нэмэлт гишүүн гарна. Суперпозицийн зарчмаар чадлыг хоёр бүрэлдэхүүний нийлбэрээр илэрхийлнэ: (1) хүчдэл тэнцүү үеийн ачааллын чадал (6.1); (2) ачаалалгүй үед хүчдэлийн зөрүүгээр үүсэх <b>тэгшитгэх урсгал </b>(уравнительная мощность):"}, {"t": "eq", "s": "Ṡтэгш = Uн·(U̇ A − U̇ B)* / Z*AB ; ṠA = ΣṠiZ*iB/Z*AB + Ṡтэгш (6.3)", "h": "Ṡ<sub>тэгш</sub> = U<sub>н</sub>·(U̇ <sub>A</sub> − U̇ <sub>B</sub>)* / Z*<sub>AB</sub> ; Ṡ<sub>A</sub> = ΣṠ<sub>i</sub>Z*<sub>iB</sub>/Z*<sub>AB</sub> + Ṡ<sub>тэгш</sub> (6.3)", "n": "6.3", "img": "data:image/png;base64,", "iw": 536}, {"t": "p", "s": "Тэгшитгэх урсгал A-гаас B руу (хүчдэл ихээс бага руу) бүх салаагаар ижил хэмжээгээр гүйнэ, B-ийн чадлаас хасагдана: ṠB = ΣṠiZ*iA/Z*AB − Ṡтэгш. Ачаалалд ямар ч хэрэггүй энэ урсгал нэмэлт алдагдал үүсгэнэ.", "h": "Тэгшитгэх урсгал A-гаас B руу (хүчдэл ихээс бага руу) бүх салаагаар ижил хэмжээгээр гүйнэ, B-ийн чадлаас хасагдана: Ṡ<sub>B</sub> = ΣṠ<sub>i</sub>Z*<sub>iA</sub>/Z*<sub>AB</sub> − Ṡ<sub>тэгш</sub>. Ачаалалд ямар ч хэрэггүй энэ урсгал нэмэлт алдагдал үүсгэнэ."}, {"t": "p", "s": "Анхаарах зүйл: Z*AB-д хуваах үйлдлээс хүчдэлийн модулийн зөрүү (UA > UB, фаз ижил) голчлон хуурмаг тэгшитгэх урсгал, харин хүчдэлийн фазын зөрүү голчлон бодит тэгшитгэх урсгал үүсгэнэ (X ≫ R үед). Энэ нь P–δ, Q–U холбоог (лекц 1) дахин баталж байна.", "h": "Анхаарах зүйл: Z*<sub>AB</sub>-д хуваах үйлдлээс хүчдэлийн <b>модулийн </b>зөрүү (U<sub>A</sub> &gt; U<sub>B</sub>, фаз ижил) голчлон <b>хуурмаг </b>тэгшитгэх урсгал, харин хүчдэлийн <b>фазын </b>зөрүү голчлон <b>бодит</b> тэгшитгэх урсгал үүсгэнэ (X ≫ R үед). Энэ нь P–δ, Q–U холбоог (лекц 1) дахин баталж байна."}, {"t": "p", "s": "Жишээ 6.3. Жишээ 6.1-ийн шугамыг A (118 кВ) ба B (116 кВ, фаз ижил) хоёр өөр дэд станцаас тэжээгдэх шугам гэж үз. Ṡтэгш = 110·(118 − 116)/(10.8 − j36.45) = 220·(10.8 + j36.45)/(10.8² + 36.45²) = 1.64 + j5.55 МВА. Иймд ṠA = 31.11 + j18.67 + 1.64 + j5.55 = 32.75 + j24.22 МВА; ṠB = 23.89 + j14.33 − 1.64 − j5.55 = 22.25 + j8.78 МВА. 2 кВ (1.8 %) хүчдэлийн зөрүү нь 5.55 Мвар хуурмаг чадал «эргэлдүүлж», A-гийн хуурмаг ачааллыг 30 %-иар өсгөв. Иймд хаалттай сүлжээнд эх үүсвэрүүдийн хүчдэлийг уялдуулан тохируулах шаардлагатай.", "h": "<b>Жишээ 6.3. </b>Жишээ 6.1-ийн шугамыг A (118 кВ) ба B (116 кВ, фаз ижил) хоёр өөр дэд станцаас тэжээгдэх шугам гэж үз. Ṡ<sub>тэгш</sub> = 110·(118 − 116)/(10.8 − j36.45) = 220·(10.8 + j36.45)/(10.8² + 36.45²) = <b>1.64 + j5.55 </b>МВА. Иймд Ṡ<sub>A</sub> = 31.11 + j18.67 + 1.64 + j5.55 = 32.75 + j24.22 МВА; Ṡ<sub>B</sub> = 23.89 + j14.33 − 1.64 − j5.55 = 22.25 + j8.78 МВА. 2 кВ (1.8 %) хүчдэлийн зөрүү нь 5.55 Мвар хуурмаг чадал «эргэлдүүлж», A-гийн хуурмаг ачааллыг 30 %-иар өсгөв. Иймд хаалттай сүлжээнд эх үүсвэрүүдийн хүчдэлийг уялдуулан тохируулах шаардлагатай.", "x": "ex"}, {"t": "p", "s": "(б) Фазын зөрүү. Одоо B-ийн хүчдэлийн модуль 118 кВ (A-тай тэнцүү), харин фаз нь −2° гэе. U̇ A − U̇ B = 118 − 118∠−2° = 0.072 + j4.118 кВ. Ṡтэгш = 110·(0.072 − j4.118)/(10.8 − j36.45) = 11.48 − j3.19 МВА. Ердөө 2°-ийн фазын зөрүү 11.5 МВт бодит чадлыг A-гаас B руу шилжүүлж байна (хуурмаг урсгал бага бөгөөд эсрэг чиглэлтэй). Хоёр тохиолдлыг харьцуулахад:", "h": "<b>(б) Фазын зөрүү. </b>Одоо B-ийн хүчдэлийн модуль 118 кВ (A-тай тэнцүү), харин фаз нь −2° гэе. U̇ <sub>A</sub> − U̇ <sub>B</sub> = 118 − 118∠−2° = 0.072 + j4.118 кВ. Ṡ<sub>тэгш</sub> = 110·(0.072 − j4.118)/(10.8 − j36.45) = <b>11.48 − j3.19 </b>МВА. Ердөө 2°-ийн фазын зөрүү 11.5 МВт бодит чадлыг A-гаас B руу шилжүүлж байна (хуурмаг урсгал бага бөгөөд эсрэг чиглэлтэй). Хоёр тохиолдлыг харьцуулахад:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Эх үүсвэрийн зөрүү", "ΔU̇ , кВ", "Ṡ , МВА тэгш", "Давамгай бүрэлдэхүүн"], "rows": [["Модуль: 118 ба 116 кВ", "2.0", "1.64 + j5.55", "Хуурмаг чадал"], ["Фаз: 0° ба −2°", "0.07 + j4.12", "11.48 − j3.19", "Бодит чадал"]]}, {"t": "cap", "s": "Хүснэгт 6.1. Тэгшитгэх урсгалын шинж", "h": "Хүснэгт 6.1. Тэгшитгэх урсгалын шинж"}, {"t": "h", "l": 1, "s": "7. Нэгэн төрлийн бус сүлжээ: байгалийн ба эдийн засгийн", "h": "<b>7. Нэгэн төрлийн бус сүлжээ: байгалийн ба эдийн засгийн</b>"}, {"t": "h", "l": 1, "s": "хуваарилалт", "h": "<b>хуваарилалт</b>"}, {"t": "p", "s": "Хаалттай сүлжээнд хүчдэлийн тэгшитгэлийн дагуу (6.1) тогтох хуваарилалтыг байгалийн хуваарилалт гэнэ; түүнийг бүрэн эсэргүүцэл Z тодорхойлно. Харин чадлын алдагдал хамгийн бага байх хуваарилалтыг эдийн засгийн гэнэ. Алдагдал ΣI²R-ийг хамгийн бага болгох нөхцөлөөс (Лагранжийн аргаар) эдийн засгийн хуваарилалт нь зөвхөн бодит эсэргүүцлээр тооцсон (6.1)-тэй ижил болно:", "h": "Хаалттай сүлжээнд хүчдэлийн тэгшитгэлийн дагуу (6.1) тогтох хуваарилалтыг <b>байгалийн </b>хуваарилалт гэнэ; түүнийг бүрэн эсэргүүцэл Z тодорхойлно. Харин чадлын алдагдал хамгийн бага байх хуваарилалтыг <b>эдийн засгийн </b>гэнэ. Алдагдал ΣI²R-ийг хамгийн бага болгох нөхцөлөөс (Лагранжийн аргаар) эдийн засгийн хуваарилалт нь <b>зөвхөн</b> <b>бодит эсэргүүцлээр </b>тооцсон (6.1)-тэй ижил болно:"}, {"t": "eq", "s": "ṠA,эк = ΣṠiRiB/RAB (6.4)", "h": "Ṡ<sub>A,эк</sub> = ΣṠ<sub>i</sub>R<sub>iB</sub>/R<sub>AB</sub> (6.4)", "n": "6.4", "img": "data:image/png;base64,", "iw": 401}, {"t": "p", "s": "Нэгэн төрлийн сүлжээнд Z-ийн харьцаа R-ийн харьцаатай тэнцүү тул байгалийн хуваарилалт эдийн засгийнхтай давхцана. Нэгэн төрлийн бус сүлжээнд (өөр огтлол, кабель ба агаарын шугам холилдсон, трансформатор оролцсон контур) хоёр хуваарилалт ялгаатай болж, нэмэлт алдагдал гарна.", "h": "Нэгэн төрлийн сүлжээнд Z-ийн харьцаа R-ийн харьцаатай тэнцүү тул байгалийн хуваарилалт эдийн засгийнхтай давхцана. Нэгэн төрлийн бус сүлжээнд (өөр огтлол, кабель ба агаарын шугам холилдсон, трансформатор оролцсон контур) хоёр хуваарилалт ялгаатай болж, нэмэлт алдагдал гарна."}, {"t": "p", "s": "Жишээ 6.4. Жишээ 6.1-ийн 2–A салааг АС-120 (z0 = 0.249 + j0.427, Z2A = 9.96 + j17.08 Ом) гэвэл:", "h": "<b>Жишээ 6.4. </b>Жишээ 6.1-ийн 2–A салааг АС-120 (z<sub>0</sub> = 0.249 + j0.427, Z<sub>2A</sub> = 9.96 + j17.08 Ом) гэвэл:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Хуваарилалт", "Ṡ , МВА A1", "Ṡ , МВА 12", "Ṡ , МВА A2", "ΔP, МВт"], "rows": [["Байгалийн (6.1), Z-ээр", "31.23 + j22.26", "1.23 + j4.26", "23.77 + j10.74", "1.002"], ["Эдийн засгийн (6.4), R-ээр", "38.83 + j23.30", "8.83 + j5.30", "16.17 + j9.70", "0.924"]]}, {"t": "cap", "s": "Хүснэгт 6.2. Нэгэн төрлийн бус цагирагийн хуваарилалт", "h": "Хүснэгт 6.2. Нэгэн төрлийн бус цагирагийн хуваарилалт"}, {"t": "p", "s": "Байгалийн хуваарилалтаар АС-120 салааны R хоёр дахин их боловч X нь бараг ижил тул тэр салаа R-тэйгээ харьцуулахад «илүү» ачаалал авч, алдагдал 8.4 %-иар (78 кВт) их байна. Эдийн засгийн хуваарилалтад шилжүүлэхийн тулд контурт ΔṠ = 7.61 + j1.04 МВА нэмэлт урсгал үүсгэх хэрэгтэй — (6.3)-ыг урвуугаар хэрэглэвэл контурт |ΔĖ| = 2.83 кВ нэмэлт ЦХХ шаардлагатай бөгөөд түүний ихэнх нь хөндлөн (фазын) бүрэлдэхүүн (j2.43 кВ).", "h": "Байгалийн хуваарилалтаар АС-120 салааны R хоёр дахин их боловч X нь бараг ижил тул тэр салаа R-тэйгээ харьцуулахад «илүү» ачаалал авч, алдагдал 8.4 %-иар (78 кВт) их байна. Эдийн засгийн хуваарилалтад шилжүүлэхийн тулд контурт ΔṠ = 7.61 + j1.04 МВА нэмэлт урсгал үүсгэх хэрэгтэй — (6.3)-ыг урвуугаар хэрэглэвэл контурт |ΔĖ| = 2.83 кВ нэмэлт ЦХХ шаардлагатай бөгөөд түүний ихэнх нь хөндлөн (фазын) бүрэлдэхүүн (j2.43 кВ).", "x": "ex"}, {"t": "h", "l": 2, "s": "Трансформатортой контур", "h": "<b>Трансформатортой контур</b>"}, {"t": "p", "s": "Хоёр трансформатор зэрэгцээ ажиллах, эсвэл өөр өөр хүчдэлийн түвшний шугамууд трансформатороор контур үүсгэх (жишээ нь 220 кВ ба 110 кВ шугамууд хоёр автотрансформатороор холбогдох) үед контурын дагуух трансформацийн коэффициентын үржвэр 1-ээс ялгаатай бол контурт тэгшитгэх ЦХХ ΔĖ үүснэ. Энэ нь ачаалалгүй үед ч эргэлдэх урсгал үүсгэнэ: Ṡтэгш = UнΔE*/Z*контур. Зарим тохиолдолд энэ ЦХХ-г ашиглан байгалийн хуваарилалтыг эдийн засгийнх руу ойртуулдаг (уртааш тохируулга).", "h": "Хоёр трансформатор зэрэгцээ ажиллах, эсвэл өөр өөр хүчдэлийн түвшний шугамууд трансформатороор контур үүсгэх (жишээ нь 220 кВ ба 110 кВ шугамууд хоёр автотрансформатороор холбогдох) үед контурын дагуух трансформацийн коэффициентын үржвэр 1-ээс ялгаатай бол контурт <b>тэгшитгэх ЦХХ </b>ΔĖ үүснэ. Энэ нь ачаалалгүй үед ч эргэлдэх урсгал үүсгэнэ: Ṡ<sub>тэгш</sub> = U<sub>н</sub>ΔE*/Z*<sub>контур</sub>. Зарим тохиолдолд энэ ЦХХ-г ашиглан байгалийн хуваарилалтыг эдийн засгийнх руу ойртуулдаг (уртааш тохируулга)."}, {"t": "p", "s": "Жишээ 6.5. Дэд станцын хоёр ТДН-16000/110 (Zт = 4.39 + j86.8 Ом) зэрэгцээ ажиллаж, нэг нь 0 салбар (115/11), нөгөө нь −2 салбар (115·(1 − 2·0.0178) = 110.9/11 кВ) дээр алдаатай тавигджээ. 110 кВ шин 115 кВ. Контурын ЦХХ (ӨХ тал руу шилжүүлсэн): ΔE =", "h": "<b>Жишээ 6.5. </b>Дэд станцын хоёр ТДН-16000/110 (Z<sub>т</sub> = 4.39 + j86.8 Ом) зэрэгцээ ажиллаж, нэг нь 0 салбар (115/11), нөгөө нь −2 салбар (115·(1 − 2·0.0178) = 110.9/11 кВ) дээр алдаатай тавигджээ. 110 кВ шин 115 кВ. Контурын ЦХХ (ӨХ тал руу шилжүүлсэн): ΔE =", "x": "ex"}, {"t": "p", "s": "115·(k1/k2 − 1) = 115·(1/0.9644 − 1) = 4.25 кВ. Контурын эсэргүүцэл 2Zт = 8.78 + j173.6 Ом. Эргэлдэх чадал Ṡтэгш = 115·4.25/(8.78 − j173.6) = 0.14 + j2.80 МВА; гүйдэл 4.25/(√3·173.8) = 14.1 А = нэрлэсэн гүйдлийн (80.3 А) 17.6 %. Ачаалалгүй ч трансформаторууд 17.6 %-иар «ачаалагдаж», хуурмаг чадлын нэмэлт алдагдал үүснэ. Иймд зэрэгцээ трансформаторуудын салбарыг ижил байлгах нь заавал (лекц 3).", "h": "115·(k<sub>1</sub>/k<sub>2</sub> − 1) = 115·(1/0.9644 − 1) = 4.25 кВ. Контурын эсэргүүцэл 2Z<sub>т</sub> = 8.78 + j173.6 Ом. Эргэлдэх чадал Ṡ<sub>тэгш</sub> = 115·4.25/(8.78 − j173.6) = <b>0.14 + j2.80 </b>МВА; гүйдэл 4.25/(√3·173.8) = 14.1 А = нэрлэсэн гүйдлийн (80.3 А) 17.6 %. Ачаалалгүй ч трансформаторууд 17.6 %-иар «ачаалагдаж», хуурмаг чадлын нэмэлт алдагдал үүснэ. Иймд зэрэгцээ трансформаторуудын салбарыг ижил байлгах нь заавал (лекц 3).", "x": "ex"}, {"t": "p", "s": "Хаалттай сүлжээнд хуваарилалтыг удирдах арга: (1) уртааш тохируулга — контурт хүчдэлийн модулийг нэмэх (РПН-тэй трансформатор, нэмэлт трансформатор); голчлон хуурмаг чадлыг шилжүүлнэ; (2) хөндлөн тохируулга — контурт фазын шилжилт оруулах (фаз шилжүүлэгч трансформатор, лекц 3); голчлон бодит чадлыг шилжүүлнэ; (3) цуваа конденсатор (X-ийг багасгах), FACTS төхөөрөмж (UPFC, TCSC); (4) хамгийн энгийн нь — контурыг тодорхой цэгт задлах (хотын сүлжээнд түгээмэл).", "h": "Хаалттай сүлжээнд хуваарилалтыг удирдах арга: (1) <b>уртааш тохируулга </b>— контурт хүчдэлийн модулийг нэмэх (РПН-тэй трансформатор, нэмэлт трансформатор); голчлон хуурмаг чадлыг шилжүүлнэ; (2) <b>хөндлөн тохируулга </b>— контурт фазын шилжилт оруулах (фаз шилжүүлэгч трансформатор, лекц 3); голчлон бодит чадлыг шилжүүлнэ; (3) цуваа конденсатор (X-ийг багасгах), FACTS төхөөрөмж (UPFC, TCSC); (4) хамгийн энгийн нь — контурыг тодорхой цэгт <b>задлах </b>(хотын сүлжээнд түгээмэл).", "x": "ex"}, {"t": "h", "l": 1, "s": "8. Ослын горим ба n−1 шалгуур", "h": "<b>8. Ослын горим ба n−1 шалгуур</b>"}, {"t": "p", "s": "Хаалттай сүлжээний давуу талыг ашиглахын тулд аль нэг элемент тасрахад үлдсэн сүлжээ бүх ачааллыг зөвшөөрөгдөх хүчдэл ба гүйдлийн хязгаарт тэжээх ёстой (n−1 шалгуур). Цагираг сүлжээний аль нэг толгой салаа тасрахад сүлжээ радиаль болж, хүчдэлийн алдагдал хэд дахин өснө.", "h": "Хаалттай сүлжээний давуу талыг ашиглахын тулд аль нэг элемент тасрахад үлдсэн сүлжээ бүх ачааллыг зөвшөөрөгдөх хүчдэл ба гүйдлийн хязгаарт тэжээх ёстой (<b>n−1</b> <b>шалгуур</b>). Цагираг сүлжээний аль нэг толгой салаа тасрахад сүлжээ радиаль болж, хүчдэлийн алдагдал хэд дахин өснө."}, {"t": "tbl", "s": "", "head": ["Горим (жишээ 6.1)", "U , кВ 1", "U , кВ 2", "Толгой салааны чадал, МВА", "ΔP, МВт"], "rows": [["Хэвийн (цагираг)", "115.02", "114.95", "31.47 + j19.89", "0.64"], ["2–A салаа тасарсан", "112.51", "110.86", "56.35 + j37.56", "1.35"], ["A–1 салаа тасарсан", "108.42", "110.45", "56.90 + j39.42", "1.90"]]}, {"t": "cap", "s": "Хүснэгт 6.3. Хэвийн ба ослын горим", "h": "Хүснэгт 6.3. Хэвийн ба ослын горим"}, {"t": "p", "s": "Хамгийн хүнд нь урт A–1 салаа тасрах горим: 1-р зангилааны хүчдэл 108.4 кВ (−1.4 %), алдагдал 3 дахин өсч, 2–A салаагаар 339 А гүйнэ (АС-240-ийн зөвшөөрөгдөх гүйдэл 610 А — хангана). Ослын горимын хүчдэлийг дэд станцын РПН-ээр засварлана.", "h": "Хамгийн хүнд нь урт A–1 салаа тасрах горим: 1-р зангилааны хүчдэл 108.4 кВ (−1.4 %), алдагдал 3 дахин өсч, 2–A салаагаар 339 А гүйнэ (АС-240-ийн зөвшөөрөгдөх гүйдэл 610 А — хангана). Ослын горимын хүчдэлийг дэд станцын РПН-ээр засварлана."}, {"t": "h", "l": 2, "s": "Түгээх цагираг сүлжээний задлах цэгийг сонгох", "h": "<b>Түгээх цагираг сүлжээний задлах цэгийг сонгох</b>"}, {"t": "p", "s": "Хотын 6–110 кВ цагираг сүлжээ хэвийн горимд ихэвчлэн задгай ажилладаг (богино залгааны гүйдлийг бууруулах, хамгаалалтыг хялбарчлах). Задлах цэгийг байгалийн хуваарилалтын хуваагдлын цэгийн ойролцоо сонговол радиаль горимын алдагдал хаалттай горимынхтой бараг тэнцүү байна:", "h": "Хотын 6–110 кВ цагираг сүлжээ хэвийн горимд ихэвчлэн задгай ажилладаг (богино залгааны гүйдлийг бууруулах, хамгаалалтыг хялбарчлах). Задлах цэгийг байгалийн хуваарилалтын <b>хуваагдлын цэгийн ойролцоо </b>сонговол радиаль горимын алдагдал хаалттай горимынхтой бараг тэнцүү байна:"}, {"t": "tbl", "s": "", "head": ["Задлах салаа (жишээ 6.1)", "U , кВ 1", "U , кВ 2", "ΔP, МВт"], "rows": [["Задлаагүй (цагираг)", "115.02", "114.95", "0.640"], ["1–2 (хуваагдлын цэгийн хажууд)", "115.13", "114.80", "0.642"], ["2–A", "112.51", "110.86", "1.352"], ["A–1", "108.42", "110.45", "1.902"]]}, {"t": "cap", "s": "Хүснэгт 6.4. Задлах цэгийн сонголт", "h": "Хүснэгт 6.4. Задлах цэгийн сонголт"}, {"t": "p", "s": "1–2 салаагаар байгалийн хуваарилалтаар ердөө 1.1 МВт гүйдэг байсан тул түүнийг задлахад алдагдал бараг өөрчлөгдөхгүй (0.3 % өснө). Ачааллын график өдөр, улирлаар өөрчлөгдөхөд оновчтой задлах цэг шилжих тул орчин үеийн түгээх сүлжээнд алсын удирдлагатай таслууруудаар сүлжээний тохиргоог (reconfiguration) өөрчилж алдагдлыг бууруулдаг (лекц 12).", "h": "1–2 салаагаар байгалийн хуваарилалтаар ердөө 1.1 МВт гүйдэг байсан тул түүнийг задлахад алдагдал бараг өөрчлөгдөхгүй (0.3 % өснө). Ачааллын график өдөр, улирлаар өөрчлөгдөхөд оновчтой задлах цэг шилжих тул орчин үеийн түгээх сүлжээнд алсын удирдлагатай таслууруудаар <b>сүлжээний тохиргоог </b>(reconfiguration) өөрчилж алдагдлыг бууруулдаг (лекц 12)."}, {"t": "h", "l": 1, "s": "9. Хаалттай сүлжээний тооцоог матрицаар хийх", "h": "<b>9. Хаалттай сүлжээний тооцоог матрицаар хийх</b>"}, {"t": "p", "s": "Олон контуртай сүлжээнд моментын дүрэм хэрэглэх боломжгүй. Ерөнхий арга нь зангилааны хүчдэлийн арга (дэлгэрэнгүй — лекц 7). Баланс зангилаа A-гийн хүчдэл мэдэгдэж байгаа тул бусад n зангилааны хувьд:", "h": "Олон контуртай сүлжээнд моментын дүрэм хэрэглэх боломжгүй. Ерөнхий арга нь <b>зангилааны хүчдэлийн арга </b>(дэлгэрэнгүй — лекц 7). Баланс зангилаа A-гийн хүчдэл мэдэгдэж байгаа тул бусад n зангилааны хувьд:"}, {"t": "eq", "s": "Yss·U + YsAUA = I ⇒U = UA·1 + Zbus·I , Zbus = Yss⁻¹ (6.5)", "h": "<b>Y</b><sub>ss</sub>·<b>U </b>+ <b>Y</b><sub>sA</sub>U<sub>A</sub> = <b>I </b>⇒<b>U </b>= U<sub>A</sub>·<b>1 </b>+ <b>Z</b><sub>bus</sub>·<b>I </b>, <b>Z</b><sub>bus</sub> = <b>Y</b><sub>ss</sub>⁻¹ (6.5)", "n": "6.5", "img": "data:image/png;base64,", "iw": 516}, {"t": "p", "s": "Энд YsA = −Yss·1 (шунтгүй сүлжээнд Y-ийн мөрийн нийлбэр тэг) гэсэн шинжийг ашиглав. Ачааллын гүйдэл хүчдэлээс хамаарах тул давталт хийнэ:", "h": "Энд <b>Y</b><sub>sA</sub> = −<b>Y</b><sub>ss</sub>·<b>1 </b>(шунтгүй сүлжээнд Y-ийн мөрийн нийлбэр тэг) гэсэн шинжийг ашиглав. Ачааллын гүйдэл хүчдэлээс хамаарах тул давталт хийнэ:"}, {"t": "eq", "s": "İk(t) = −(Ṡk / U̇ k(t))* ; U(t+1) = UA·1 + Zbus·I(t) (6.6)", "h": "İ<sub>k</sub><sup>(t)</sup> = −(Ṡ<sub>k</sub> / U̇ <sub>k</sub><sup>(t)</sup>)* ; <b>U</b><sup>(t+1)</sup> = U<sub>A</sub>·<b>1 </b>+ <b>Z</b><sub>bus</sub>·<b>I</b><sup>(t)</sup> (6.6)", "n": "6.6", "img": "data:image/png;base64,", "iw": 490}, {"t": "p", "s": "(Хүчдэлийг кВ (шугамын), чадлыг МВА-аар авбал «гүйдэл» нь √3I, кА болно; хэмжээсүүд зохицно.) Энэ нь лекц 5-ын DLF аргын ерөнхийлөл: радиаль сүлжээнд Zbus = DLF.", "h": "(Хүчдэлийг кВ (шугамын), чадлыг МВА-аар авбал «гүйдэл» нь √3I, кА болно; хэмжээсүүд зохицно.) Энэ нь лекц 5-ын DLF аргын ерөнхийлөл: радиаль сүлжээнд <b>Z</b><sub>bus</sub> = <b>DLF</b>."}, {"t": "p", "s": "Жишээ 6.6. Жишээ 6.1-ийг матрицаар. Салааны дамжууламж: yA1 = 1/(3.6 + j12.15) = 0.02242 − j0.07566; y12 = 0.03363 − j0.11349; y2A = 0.01681 − j0.05675 См.", "h": "<b>Жишээ 6.6. Жишээ 6.1-ийг матрицаар. </b>Салааны дамжууламж: y<sub>A1</sub> = 1/(3.6 + j12.15) = 0.02242 − j0.07566; y<sub>12</sub> = 0.03363 − j0.11349; y<sub>2A</sub> = 0.01681 − j0.05675 См.", "x": "ex"}, {"t": "p", "s": "1. Бүтэн Y матриц (зангилаа A, 1, 2), См:", "h": "1. Бүтэн Y матриц (зангилаа A, 1, 2), См:", "x": "ex"}, {"t": "p", "s": "0.03923 − j0.13241 −0.02242 + j0.07566 −0.01681 + j0.05675 Y = −0.02242 + j0.07566 0.05605 − j0.18916 −0.03363 + j0.11349 (6.7)", "h": "0.03923 − j0.13241 −0.02242 + j0.07566 −0.01681 + j0.05675 <b>Y </b>= −0.02242 + j0.07566 0.05605 − j0.18916 −0.03363 + j0.11349 (6.7)", "x": "ex"}, {"t": "p", "s": "−0.01681 + j0.05675 −0.03363 + j0.11349 0.05044 − j0.17024", "h": "−0.01681 + j0.05675 −0.03363 + j0.11349 0.05044 − j0.17024", "x": "ex"}, {"t": "p", "s": "2. Баланс зангилааг хасч Yss (2×2)-ийг урвуулбал:", "h": "2. Баланс зангилааг хасч <b>Y</b><sub>ss</sub> (2×2)-ийг урвуулбал:", "x": "ex"}, {"t": "p", "s": "2.400 + j8.100 1.600 + j5.400", "h": "2.400 + j8.100 1.600 + j5.400", "x": "ex"}, {"t": "eq", "s": "Zbus = Yss⁻¹ = Ом (6.8)", "h": "<b>Z</b><sub>bus</sub> = <b>Y</b><sub>ss</sub>⁻¹ = Ом (6.8)", "n": "6.8", "img": "data:image/png;base64,", "iw": 495}, {"t": "p", "s": "1.600 + j5.400 2.667 + j9.000", "h": "1.600 + j5.400 2.667 + j9.000", "x": "ex"}, {"t": "p", "s": "Тайлбар: Z11 = ZA1 ∥ (Z12 + Z2A) = (3.6 + j12.15)·(7.2 + j24.3)/(10.8 + j36.45) = 2.4 + j8.1 — 1-р зангилаанаас A руу харсан эквивалент эсэргүүцэл; Z12 — 1-д тарьсан гүйдэл 2-ын хүчдэлд үзүүлэх нөлөө. Zbus-ийн элементүүд нэгэн төрлийн сүлжээнд z0-д пропорциональ байна.", "h": "Тайлбар: Z<sub>11</sub> = Z<sub>A1</sub> ∥ (Z<sub>12</sub> + Z<sub>2A</sub>) = (3.6 + j12.15)·(7.2 + j24.3)/(10.8 + j36.45) = 2.4 + j8.1 — 1-р зангилаанаас A руу харсан эквивалент эсэргүүцэл; Z<sub>12</sub> — 1-д тарьсан гүйдэл 2-ын хүчдэлд үзүүлэх нөлөө. <b>Z</b><sub>bus</sub>-ийн элементүүд нэгэн төрлийн сүлжээнд z<sub>0</sub>-д пропорциональ байна.", "x": "ex"}, {"t": "p", "s": "3. Давталт (6.6), UA = 118 кВ:", "h": "3. Давталт (6.6), U<sub>A</sub> = 118 кВ:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["t", "İ , кА 1", "İ , кА 2", "U̇ , кВ 1", "U̇ , кВ 2", "|U | 1", "|U | 2"], "rows": [["0", "−0.2542 + j0.1525", "−0.2119 + j0.1271", "115.129 − j2.634", "115.060 − j2.697", "115.159", "115.092"], ["1", "−0.2569 + j0.1622", "−0.2141 + j0.1354", "114.996 − j2.631", "114.924 − j2.693", "115.026", "114.955"], ["2", "−0.2572 + j0.1624", "−0.2144 + j0.1356", "114.992 − j2.634", "114.920 − j2.697", "115.023", "114.952"], ["3", "−0.2572 + j0.1624", "−0.2144 + j0.1356", "114.992 − j2.634", "114.920 − j2.697", "115.022", "114.951"]]}, {"t": "cap", "s": "Хүснэгт 6.5. Zbus давталт (t = 0 үед U = 118 кВ-оор эхэлсэн)", "h": "Хүснэгт 6.5. <b>Z</b><sub>bus</sub> давталт (t = 0 үед U = 118 кВ-оор эхэлсэн)"}, {"t": "p", "s": "4. Үр дүн: U1 = 115.02 кВ ∠−1.31°, U2 = 114.95 кВ ∠−1.34°. Салааны чадал ṠA1 = UA·[(UA − U̇ 1)yA1]* = 31.47 + j19.89 МВА; ṠA2 = 24.17 + j15.28 МВА. Нийт алдагдал 55.64 + j35.16 − 55 − j33 = 0.64 + j2.16 МВА. Гурван давталтаар 10⁻³ кВ нарийвчлалд нийлэв.", "h": "4. Үр дүн: U<sub>1</sub> = 115.02 кВ ∠−1.31°, U<sub>2</sub> = 114.95 кВ ∠−1.34°. Салааны чадал Ṡ<sub>A1</sub> = U<sub>A</sub>·[(U<sub>A</sub> − U̇ <sub>1</sub>)y<sub>A1</sub>]* = 31.47 + j19.89 МВА; Ṡ<sub>A2</sub> = 24.17 + j15.28 МВА. Нийт алдагдал 55.64 + j35.16 − 55 − j33 = <b>0.64 + j2.16 </b>МВА. Гурван давталтаар 10⁻³ кВ нарийвчлалд нийлэв.", "x": "ex"}, {"t": "h", "l": 2, "s": "Алдагдлыг Zbus-аар илэрхийлэх", "h": "<b>Алдагдлыг Z</b><sub>bus</sub><b>-аар илэрхийлэх</b>"}, {"t": "p", "s": "Шунтгүй сүлжээнд баланс зангилааны гүйдэл İA = −Σİk тул бүх зангилааны тарилтын нийлбэр буюу сүлжээний алдагдал:", "h": "Шунтгүй сүлжээнд баланс зангилааны гүйдэл İ<sub>A</sub> = −Σİ<sub>k</sub> тул бүх зангилааны тарилтын нийлбэр буюу сүлжээний алдагдал:"}, {"t": "eq", "s": "ΔṠ = Σk(U̇ k − UA)İ*k = Iᴴ·Zbus·I ; ΔP = Iᴴ·Rbus·I , Rbus = Re Zbus (6.12)", "h": "ΔṠ = Σ<sub>k</sub>(U̇ <sub>k</sub> − U<sub>A</sub>)İ*<sub>k</sub> = <b>I</b>ᴴ·<b>Z</b><sub>bus</sub>·<b>I </b>; ΔP = <b>I</b>ᴴ·<b>R</b><sub>bus</sub>·<b>I </b>, <b>R</b><sub>bus</sub> = Re <b>Z</b><sub>bus</sub> (6.12)", "n": "6.12", "img": "data:image/png;base64,", "iw": 551}, {"t": "p", "s": "Жишээ 6.6-ийн нийлсэн гүйдлээр: IᴴZbusI = 0.640 + j2.161 МВА — салааны алдагдлын нийлбэртэй яг тэнцүү. (6.12) нь зангилааны гүйдлээр (тарилтаар) алдагдлыг шууд илэрхийлэх тул алдагдлын коэффициентын (Кроны B-коэффициент) томьёоны үндэс болно: генераторуудын ачааллыг оновчтой хуваарилахад ΔP = ΣiΣjPiBijPj хэлбэрээр хэрэглэнэ. Мөн аль зангилааны ачааллыг өөрчлөхөд алдагдал хэрхэн өөрчлөгдөхийг (∂ΔP/ ∂Pk — алдагдлын өсөлтийн харьцаа) тодорхойлох боломж олгоно (лекц 12).", "h": "Жишээ 6.6-ийн нийлсэн гүйдлээр: <b>I</b>ᴴ<b>Z</b><sub>bus</sub><b>I </b>= 0.640 + j2.161 МВА — салааны алдагдлын нийлбэртэй яг тэнцүү. (6.12) нь зангилааны гүйдлээр (тарилтаар) алдагдлыг шууд илэрхийлэх тул <b>алдагдлын коэффициентын </b>(Кроны B-коэффициент) томьёоны үндэс болно: генераторуудын ачааллыг оновчтой хуваарилахад ΔP = Σ<sub>i</sub>Σ<sub>j</sub>P<sub>i</sub>B<sub>ij</sub>P<sub>j</sub> хэлбэрээр хэрэглэнэ. Мөн аль зангилааны ачааллыг өөрчлөхөд алдагдал хэрхэн өөрчлөгдөхийг (∂ΔP/ ∂P<sub>k</sub> — алдагдлын өсөлтийн харьцаа) тодорхойлох боломж олгоно (лекц 12).", "x": "ex"}, {"t": "h", "l": 1, "s": "10. Нийлмэл сүлжээг хялбарчлах: Кроны бууруулалт", "h": "<b>10. Нийлмэл сүлжээг хялбарчлах: Кроны бууруулалт</b>"}, {"t": "p", "s": "Ачаалалгүй (транзит) зангилааг тэгшитгэлээс хасч сүлжээг хялбарчилж болно. Зангилаа k-д гүйдэл тарихгүй (Ik = 0) бол түүний тэгшитгэлээс Uk-г илэрхийлж бусад тэгшитгэлд орлуулна:", "h": "Ачаалалгүй (транзит) зангилааг тэгшитгэлээс хасч сүлжээг хялбарчилж болно. Зангилаа k-д гүйдэл тарихгүй (I<sub>k</sub> = 0) бол түүний тэгшитгэлээс U<sub>k</sub>-г илэрхийлж бусад тэгшитгэлд орлуулна:"}, {"t": "eq", "s": "Y′ij = Yij − YikYkj/Ykk , i, j ≠ k (6.9)", "h": "Y′<sub>ij</sub> = Y<sub>ij</sub> − Y<sub>ik</sub>Y<sub>kj</sub>/Y<sub>kk</sub> , i, j ≠ k (6.9)", "n": "6.9", "img": "data:image/png;base64,", "iw": 434}, {"t": "p", "s": "Энэ нь Кроны бууруулалт бөгөөд Гауссын хасалтын нэг алхамтай ижил (лекц 8). Схемийн хувьд энэ нь «од → гурвалжин» хувиргалтын ерөнхийлөл. Жишээлбэл, гурван салаа нийлсэн зангилааг хасахад yij′ = yiyj/(y1 + y2 + y3) дамжууламжтай гурвалжин үүснэ. Гар тооцоонд нийлмэл сүлжээг хувиргалтаар хоёр талаас тэжээгдэх шугам хүртэл", "h": "Энэ нь <b>Кроны бууруулалт </b>бөгөөд Гауссын хасалтын нэг алхамтай ижил (лекц 8). Схемийн хувьд энэ нь «од → гурвалжин» хувиргалтын ерөнхийлөл. Жишээлбэл, гурван салаа нийлсэн зангилааг хасахад y<sub>ij</sub>′ = y<sub>i</sub>y<sub>j</sub>/(y<sub>1</sub> + y<sub>2</sub> + y<sub>3</sub>) дамжууламжтай гурвалжин үүснэ. Гар тооцоонд нийлмэл сүлжээг хувиргалтаар хоёр талаас тэжээгдэх шугам хүртэл"}, {"t": "p", "s": "хялбарчилж, (6.1)-ийг хэрэглээд, буцааж задлах арга түгээмэл байсан. Орчин үед энэ арга нь эквивалентчлал (хөрш системийг цөөн зангилаагаар төлөөлөх) болон богино залгааны тооцоонд ашиглагдана.", "h": "хялбарчилж, (6.1)-ийг хэрэглээд, буцааж задлах арга түгээмэл байсан. Орчин үед энэ арга нь эквивалентчлал (хөрш системийг цөөн зангилаагаар төлөөлөх) болон богино залгааны тооцоонд ашиглагдана."}, {"t": "h", "l": 2, "s": "Контурын гүйдлийн арга", "h": "<b>Контурын гүйдлийн арга</b>"}, {"t": "p", "s": "Хаалттай сүлжээг контурын тэгшитгэлээр бас тооцож болно: контур бүрт контурын гүйдэл (эсвэл чадал) Ṡк-г үл мэдэгдэгч болгож, Zконтур·Ṡ*к = Eк хэлбэрийн системийг бичнэ. Үл мэдэгдэгчийн тоо = бие даасан контурын тоо, зангилааны аргынхаас цөөн байж болох ч матрицыг байгуулахад сүлжээний граф шаардлагатай (лекц 7). Жишээ 6.1-д ганц контур тул A–1 салааны чадлыг Ṡк гэвэл контурын хүчдэлийн тэгшитгэл: ṠкZ*A1 + (Ṡк − Ṡ1)Z*12 + (Ṡк − Ṡ1 − Ṡ2)Z*2A = 0 ⇒ Ṡк = [Ṡ1(Z*12 + Z*2A) + Ṡ2Z*2A]/Z*Σ = 31.11 + j18.67 МВА — (6.1)-тэй ижил. Өөрөөр хэлбэл моментын дүрэм нь нэг контурт хэрэглэсэн контурын арга юм. Компьютерийн програмд матриц нь сийрэг, автоматаар байгуулагдах зангилааны аргыг илүүд үздэг.", "h": "Хаалттай сүлжээг контурын тэгшитгэлээр бас тооцож болно: контур бүрт контурын гүйдэл (эсвэл чадал) Ṡ<sub>к</sub>-г үл мэдэгдэгч болгож, <b>Z</b><sub>контур</sub>·<b>Ṡ</b>*<sub>к</sub> = <b>E</b><sub>к</sub> хэлбэрийн системийг бичнэ. Үл мэдэгдэгчийн тоо = бие даасан контурын тоо, зангилааны аргынхаас цөөн байж болох ч матрицыг байгуулахад сүлжээний граф шаардлагатай (лекц 7). Жишээ 6.1-д ганц контур тул A–1 салааны чадлыг Ṡ<sub>к</sub> гэвэл контурын хүчдэлийн тэгшитгэл: Ṡ<sub>к</sub>Z*<sub>A1</sub> + (Ṡ<sub>к</sub> − Ṡ<sub>1</sub>)Z*<sub>12</sub> + (Ṡ<sub>к</sub> − Ṡ<sub>1</sub> − Ṡ<sub>2</sub>)Z*<sub>2A</sub> = 0 ⇒ Ṡ<sub>к</sub> = [Ṡ<sub>1</sub>(Z*<sub>12</sub> + Z*<sub>2A</sub>) + Ṡ<sub>2</sub>Z*<sub>2A</sub>]/Z*<sub>Σ</sub> = 31.11 + j18.67 МВА — (6.1)-тэй ижил. Өөрөөр хэлбэл моментын дүрэм нь нэг контурт хэрэглэсэн контурын арга юм. Компьютерийн програмд матриц нь сийрэг, автоматаар байгуулагдах зангилааны аргыг илүүд үздэг."}, {"t": "h", "l": 2, "s": "Хоёр эх үүсвэрийн хоорондох чадлын дамжуулалт", "h": "<b>Хоёр эх үүсвэрийн хоорондох чадлын дамжуулалт</b>"}, {"t": "p", "s": "Хоёр талаас тэжээгдэх шугамын хоёр үзүүрт хүчтэй эх үүсвэр (систем) байвал тэдгээрийн хоорондох бодит чадлын дамжуулалтыг хүчдэлийн фазын зөрүү тодорхойлно. R ≪ X үед:", "h": "Хоёр талаас тэжээгдэх шугамын хоёр үзүүрт хүчтэй эх үүсвэр (систем) байвал тэдгээрийн хоорондох бодит чадлын дамжуулалтыг хүчдэлийн фазын зөрүү тодорхойлно. R ≪ X үед:"}, {"t": "eq", "s": "P = UAUBsinδ/X ; QA = (UA² − UAUBcosδ)/X (6.13)", "h": "P = U<sub>A</sub>U<sub>B</sub>sinδ/X ; Q<sub>A</sub> = (U<sub>A</sub>² − U<sub>A</sub>U<sub>B</sub>cosδ)/X (6.13)", "n": "6.13", "img": "data:image/png;base64,", "iw": 487}, {"t": "p", "s": "Жишээ. Хоёр системийг холбох 220 кВ, 200 км шугамаар (X = 0.42·200 = 84 Ом) 150 МВт дамжуулах. UA = UB = 220 кВ бол sinδ = 150·84/220² = 0.260 → δ = 15.1°. Онолын дээд хязгаар Pmax = 220²/84 = 576 МВт; 150 МВт нь түүний 26 % — статик тогтворжилтын нөөц хангалттай. Хоёр үзүүр тус бүр 220²(1 − cos15.1°)/84 = 19.9 Мвар хуурмаг чадал шугамд өгнө (шугамын X-д алдагдах хуурмаг чадал). Тэгшитгэх урсгалын (6.3) томьёо нь (6.13)-ын бага δ-ийн ойролцоолол юм.", "h": "<b>Жишээ. </b>Хоёр системийг холбох 220 кВ, 200 км шугамаар (X = 0.42·200 = 84 Ом) 150 МВт дамжуулах. U<sub>A</sub> = U<sub>B</sub> = 220 кВ бол sinδ = 150·84/220² = 0.260 → δ = 15.1°. Онолын дээд хязгаар P<sub>max</sub> = 220²/84 = 576 МВт; 150 МВт нь түүний 26 % — статик тогтворжилтын нөөц хангалттай. Хоёр үзүүр тус бүр 220²(1 − cos15.1°)/84 = 19.9 Мвар хуурмаг чадал шугамд өгнө (шугамын X-д алдагдах хуурмаг чадал). Тэгшитгэх урсгалын (6.3) томьёо нь (6.13)-ын бага δ-ийн ойролцоолол юм."}, {"t": "h", "l": 2, "s": "Хаалттай сүлжээний тооцооны ерөнхий алгоритм", "h": "<b>Хаалттай сүлжээний тооцооны ерөнхий алгоритм</b>"}, {"t": "p", "s": "1. Орлуулах схем байгуулж (лекц 2–4), дэд станцуудыг тооцооны ачааллаар төлөөлөх.", "h": "1. Орлуулах схем байгуулж (лекц 2–4), дэд станцуудыг тооцооны ачааллаар төлөөлөх."}, {"t": "p", "s": "2. Сүлжээ нэг контуртай бол (6.1)/(6.2)-оор, эх үүсвэрийн хүчдэл ялгаатай бол (6.3)-ыг нэмж урьдчилсан хуваарилалт олох.", "h": "2. Сүлжээ нэг контуртай бол (6.1)/(6.2)-оор, эх үүсвэрийн хүчдэл ялгаатай бол (6.3)-ыг нэмж урьдчилсан хуваарилалт олох."}, {"t": "p", "s": "3. Чадлын хуваагдлын цэгийг (▼, ▽) тодорхойлж, задалсан радиаль хэсгүүдийг лекц 5-ын аргаар нарийвчлан тооцох.", "h": "3. Чадлын хуваагдлын цэгийг (▼, ▽) тодорхойлж, задалсан радиаль хэсгүүдийг лекц 5-ын аргаар нарийвчлан тооцох."}, {"t": "p", "s": "4. Олон контуртай бол Кроны бууруулалт/хувиргалтаар хялбарчлах, эсвэл шууд Zbus давталт (6.6) хэрэглэх.", "h": "4. Олон контуртай бол Кроны бууруулалт/хувиргалтаар хялбарчлах, эсвэл шууд <b>Z</b><sub>bus</sub> давталт (6.6) хэрэглэх."}, {"t": "p", "s": "5. Хүчдэл, гүйдэл, алдагдлыг шалгаж, n−1 горим бүрийг давтан тооцох.", "h": "5. Хүчдэл, гүйдэл, алдагдлыг шалгаж, n−1 горим бүрийг давтан тооцох."}, {"t": "p", "s": "6. Шаардлагатай бол хуваарилалтыг удирдах арга хэмжээ (уртааш-хөндлөн тохируулга, задлах цэг) сонгох.", "h": "6. Шаардлагатай бол хуваарилалтыг удирдах арга хэмжээ (уртааш-хөндлөн тохируулга, задлах цэг) сонгох."}, {"t": "h", "l": 1, "s": "11. Жишээ: стендийн 3 зангилааны цагираг", "h": "<b>11. Жишээ: стендийн 3 зангилааны цагираг</b>"}, {"t": "p", "s": "Жишээ 6.7. Лабораторийн стендийн «3 зангилаа» схем (Sб = 100 МВА): z12 = 0.02 + j0.04, z13 = 0.01 + j0.03, z23 = 0.0125 + j0.025 о.н.; 1 — баланс (1.05∠0°), 2 — ачаалал 4.0 + j2.5 о.н., 3 — генератор 2.0 о.н. Генераторын хуурмаг чадлыг стендийн үр дүнгээс Q3 = 1.4618 о.н. гэж авч, Zbus аргаар хүчдэлийг тооцоод стендийн Ньютон-Рафсоны шийдэлтэй тулгана уу.", "h": "<b>Жишээ 6.7. </b>Лабораторийн стендийн «3 зангилаа» схем (S<sub>б</sub> = 100 МВА): z<sub>12</sub> = 0.02 + j0.04, z<sub>13</sub> = 0.01 + j0.03, z<sub>23</sub> = 0.0125 + j0.025 о.н.; 1 — баланс (1.05∠0°), 2 — ачаалал 4.0 + j2.5 о.н., 3 — генератор 2.0 о.н. Генераторын хуурмаг чадлыг стендийн үр дүнгээс Q<sub>3</sub> = 1.4618 о.н. гэж авч, <b>Z</b><sub>bus</sub> аргаар хүчдэлийг тооцоод стендийн Ньютон-Рафсоны шийдэлтэй тулгана уу.", "x": "ex"}, {"t": "p", "s": "1. Y матриц (y12 = 10 − j20, y13 = 10 − j30, y23 = 16 − j32):", "h": "1. Y матриц (y<sub>12</sub> = 10 − j20, y<sub>13</sub> = 10 − j30, y<sub>23</sub> = 16 − j32):", "x": "ex"}, {"t": "p", "s": "20 − j50 −10 + j20 −10 + j30 Y = −10 + j20 26 − j52 −16 + j32 (6.10)", "h": "20 − j50 −10 + j20 −10 + j30 <b>Y </b>= −10 + j20 26 − j52 −16 + j32 (6.10)", "x": "ex"}, {"t": "p", "s": "−10 + j30 −16 + j32 26 − j62", "h": "−10 + j30 −16 + j32 26 − j62", "x": "ex"}, {"t": "p", "s": "2. Баланс зангилааг хасч урвуулсан:", "h": "2. Баланс зангилааг хасч урвуулсан:", "x": "ex"}, {"t": "p", "s": "0.0107 + j0.0232 0.0048 + j0.0127", "h": "0.0107 + j0.0232 0.0048 + j0.0127", "x": "ex"}, {"t": "eq", "s": "Zbus = о.н. (6.11)", "h": "<b>Z</b><sub>bus</sub> = о.н. (6.11)", "n": "6.11", "img": "data:image/png;base64,", "iw": 486}, {"t": "p", "s": "0.0048 + j0.0127 0.0079 + j0.0206", "h": "0.0048 + j0.0127 0.0079 + j0.0206", "x": "ex"}, {"t": "p", "s": "3. Давталт U = 1.05·1 + Zbus·(S/U)*, S = [−4 − j2.5; 2 + j1.4618]:", "h": "3. Давталт <b>U </b>= 1.05·<b>1 </b>+ <b>Z</b><sub>bus</sub>·(<b>S</b>/<b>U</b>)*, <b>S </b>= [−4 − j2.5; 2 + j1.4618]:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["t", "|U | 2", "δ , ° 2", "|U | 3", "δ , ° 3"], "rows": [["0", "0.9821", "−2.657", "1.0451", "−0.466"], ["1", "0.9727", "−2.663", "1.0404", "−0.485"], ["2", "0.9718", "−2.696", "1.0401", "−0.498"], ["3", "0.9717", "−2.696", "1.0400", "−0.499"]]}, {"t": "cap", "s": "Хүснэгт 6.6. Стендийн схемийн Zbus давталт", "h": "Хүснэгт 6.6. Стендийн схемийн <b>Z</b><sub>bus</sub> давталт"}, {"t": "p", "s": "4. Салааны урсгал Ṡij = U̇ i[(U̇ i − U̇ j)yij]*·100: 1→2: 179.36 + j118.73 МВА; 1→3: 39.06 + j22.12 МВА; 3→2 (2-р зангилаанд хүрэх): 229.03 + j148.05 МВА. Баланс зангилааны чадал Ṡ1 = 218.42 + j140.85 МВА.", "h": "4. Салааны урсгал Ṡ<sub>ij</sub> = U̇ <sub>i</sub>[(U̇ <sub>i</sub> − U̇ <sub>j</sub>)y<sub>ij</sub>]*·100: 1→2: 179.36 + j118.73 МВА; 1→3: 39.06 + j22.12 МВА; 3→2 (2-р зангилаанд хүрэх): 229.03 + j148.05 МВА. Баланс зангилааны чадал Ṡ<sub>1</sub> = 218.42 + j140.85 МВА.", "x": "ex"}, {"t": "p", "s": "5. Дүгнэлт. Үр дүн стендийн Ньютон-Рафсоны шийдэлтэй (U2 = 0.9717∠−2.696°, δ3 = −0.499°, S1 = 218.42 + j140.85) бүрэн давхцав; |U3| = 1.040 болсон нь Q3-ын утга зөв гэдгийг баталж байна. 2-р зангилаа хоёр талаас (1 ба 3-аас) тэжээгдэх — чадлын хуваагдлын цэг; ачааллын 57 % нь ойр, бага эсэргүүцэлтэй 3-р зангилаанаас ирж байна. Жинхэнэ тооцоонд Q3 мэдэгдэхгүй (PV зангилаа) — үүнийг лекц 9–10-д авч үзнэ.", "h": "5. Дүгнэлт. Үр дүн стендийн Ньютон-Рафсоны шийдэлтэй (U<sub>2</sub> = 0.9717∠−2.696°, δ<sub>3</sub> = −0.499°, S<sub>1</sub> = 218.42 + j140.85) бүрэн давхцав; |U<sub>3</sub>| = 1.040 болсон нь Q<sub>3</sub>-ын утга зөв гэдгийг баталж байна. 2-р зангилаа хоёр талаас (1 ба 3-аас) тэжээгдэх — чадлын хуваагдлын цэг; ачааллын 57 % нь ойр, бага эсэргүүцэлтэй 3-р зангилаанаас ирж байна. Жинхэнэ тооцоонд Q<sub>3</sub> мэдэгдэхгүй (PV зангилаа) — үүнийг лекц 9–10-д авч үзнэ.", "x": "ex"}, {"t": "h", "l": 1, "s": "12. Лабораторийн стендтэй холбоо", "h": "<b>12. Лабораторийн стендтэй холбоо</b>"}, {"t": "p", "s": "Стенд дээр шалгах (лекц 6). Стендийн «3 зангилаа» схем нь 1–2, 1–3, 2–3 гурван шугамтай цагираг бөгөөд 1 (баланс, 1.05) ба 3 (PV, 200 МВт) зангилаанаас тэжээгдэх — хоёр талаас тэжээгдэх сүлжээний жишээ. (1) F7-оор бодоод «6. Үр дүн» хуудаснаас салааны урсгалыг бич; 2-р зангилаа хуваагдлын цэг болохыг харуул. (2) Хүчдэлийг 1.0 о.н. гэж үзэж (6.1)-ээр 2-р зангилааны ачааллын хуваарилалтыг гараар тооцоод стендтэй харьцуул (3-р генераторын 200 МВт-ыг сөрөг ачаалал гэж үз). (3) 3-р зангилааны хүчдэлийг 1.04-өөс 1.06 болгоход тэгшитгэх хуурмаг урсгал хэрхэн өөрчлөгдөхийг тодорхойл. (4) Шугам 1–3-ыг «тасалж» (z-ийг маш их болгож) n−1 горимыг шалга.", "h": "<b>Стенд дээр шалгах (лекц 6). </b>Стендийн «3 зангилаа» схем нь 1–2, 1–3, 2–3 гурван шугамтай <b>цагираг </b>бөгөөд 1 (баланс, 1.05) ба 3 (PV, 200 МВт) зангилаанаас тэжээгдэх — хоёр талаас тэжээгдэх сүлжээний жишээ. (1) F7-оор бодоод «6. Үр дүн» хуудаснаас салааны урсгалыг бич; 2-р зангилаа хуваагдлын цэг болохыг харуул. (2) Хүчдэлийг 1.0 о.н. гэж үзэж (6.1)-ээр 2-р зангилааны ачааллын хуваарилалтыг гараар тооцоод стендтэй харьцуул (3-р генераторын 200 МВт-ыг сөрөг ачаалал гэж үз). (3) 3-р зангилааны хүчдэлийг 1.04-өөс 1.06 болгоход тэгшитгэх хуурмаг урсгал хэрхэн өөрчлөгдөхийг тодорхойл. (4) Шугам 1–3-ыг «тасалж» (z-ийг маш их болгож) n−1 горимыг шалга."}, {"t": "h", "l": 1, "s": "Дүгнэлт", "h": "<b>Дүгнэлт</b>"}, {"t": "p", "s": "Хоёр талаас тэжээгдэх шугамын чадлын хуваарилалт — эсэргүүцлийн моментын дүрэм (6.1); нэгэн төрлийн сүлжээнд уртаар (6.2).", "h": "Хоёр талаас тэжээгдэх шугамын чадлын хуваарилалт — эсэргүүцлийн моментын дүрэм (6.1); нэгэн төрлийн сүлжээнд уртаар (6.2)."}, {"t": "p", "s": "Чадлын хуваагдлын цэгээр задалж, хоёр радиаль сүлжээ болгон нарийвчилж тооцно. Эх үүсвэрийн хүчдэлийн зөрүү ачаалалд хамааралгүй тэгшитгэх урсгал үүсгэнэ (6.3): модулийн зөрүү — голчлон хуурмаг, фазын зөрүү — голчлон бодит. Байгалийн хуваарилалтыг Z, эдийн засгийнхыг R тодорхойлно; нэгэн төрлийн бус сүлжээнд уртааш-хөндлөн тохируулгаар ойртуулна.", "h": "Чадлын хуваагдлын цэгээр задалж, хоёр радиаль сүлжээ болгон нарийвчилж тооцно. Эх үүсвэрийн хүчдэлийн зөрүү ачаалалд хамааралгүй тэгшитгэх урсгал үүсгэнэ (6.3): модулийн зөрүү — голчлон хуурмаг, фазын зөрүү — голчлон бодит. Байгалийн хуваарилалтыг Z, эдийн засгийнхыг R тодорхойлно; нэгэн төрлийн бус сүлжээнд уртааш-хөндлөн тохируулгаар ойртуулна."}, {"t": "p", "s": "n−1 горимд сүлжээ радиаль болж, хүчдэл ба алдагдлыг шалгах шаардлагатай. Ерөнхий арга: U = UA1 + ZbusI давталт; Кроны бууруулалт (6.9).", "h": "n−1 горимд сүлжээ радиаль болж, хүчдэл ба алдагдлыг шалгах шаардлагатай. Ерөнхий арга: <b>U </b>= U<sub>A</sub><b>1 </b>+ <b>Z</b><sub>bus</sub><b>I </b>давталт; Кроны бууруулалт (6.9)."}, {"t": "h", "l": 1, "s": "Хяналтын асуулт", "h": "<b>Хяналтын асуулт</b>"}, {"t": "p", "s": "1. Хаалттай сүлжээний давуу ба сул талыг нэрлэ.", "h": "1. Хаалттай сүлжээний давуу ба сул талыг нэрлэ."}, {"t": "p", "s": "2. Эсэргүүцлийн моментын дүрмийг (6.1) гарга.", "h": "2. Эсэргүүцлийн моментын дүрмийг (6.1) гарга."}, {"t": "p", "s": "3. Нэгэн төрлийн сүлжээ гэж юу вэ? Хуваарилалт яагаад уртаар тодорхойлогдох вэ?", "h": "3. Нэгэн төрлийн сүлжээ гэж юу вэ? Хуваарилалт яагаад уртаар тодорхойлогдох вэ?"}, {"t": "p", "s": "4. Чадлын хуваагдлын цэгийг хэрхэн тодорхойлж, ямар зорилгоор ашиглах вэ?", "h": "4. Чадлын хуваагдлын цэгийг хэрхэн тодорхойлж, ямар зорилгоор ашиглах вэ?"}, {"t": "p", "s": "5. Тэгшитгэх урсгалын томьёо, түүний физик утга.", "h": "5. Тэгшитгэх урсгалын томьёо, түүний физик утга."}, {"t": "p", "s": "6. Яагаад хүчдэлийн модулийн зөрүү голчлон хуурмаг урсгал үүсгэдэг вэ?", "h": "6. Яагаад хүчдэлийн модулийн зөрүү голчлон хуурмаг урсгал үүсгэдэг вэ?"}, {"t": "p", "s": "7. Байгалийн ба эдийн засгийн хуваарилалтын ялгаа.", "h": "7. Байгалийн ба эдийн засгийн хуваарилалтын ялгаа."}, {"t": "p", "s": "8. Хаалттай сүлжээний чадлын урсгалыг удирдах аргуудыг нэрлэ.", "h": "8. Хаалттай сүлжээний чадлын урсгалыг удирдах аргуудыг нэрлэ."}, {"t": "p", "s": "9. Zbus матрицын диагональ элементийн физик утга.", "h": "9. <b>Z</b><sub>bus</sub> матрицын диагональ элементийн физик утга."}, {"t": "p", "s": "10. Кроны бууруулалтын томьёо ба хэрэглээ.", "h": "10. Кроны бууруулалтын томьёо ба хэрэглээ."}, {"t": "h", "l": 1, "s": "Бие даалтын даалгавар", "h": "<b>Бие даалтын даалгавар</b>"}, {"t": "p", "s": "1. Жишээ 6.1-д 1–2 салаанд 10 Мвар конденсатор 2-р зангилаанд залгавал хуваарилалт ба алдагдлыг (6.2)-оор тооцоол.", "h": "1. Жишээ 6.1-д 1–2 салаанд 10 Мвар конденсатор 2-р зангилаанд залгавал хуваарилалт ба алдагдлыг (6.2)-оор тооцоол."}, {"t": "p", "s": "2. Жишээ 6.3-т B-ийн хүчдэлийг 118 кВ, фазыг −2° гэвэл тэгшитгэх урсгалыг тооцоол.", "h": "2. Жишээ 6.3-т B-ийн хүчдэлийг 118 кВ, фазыг −2° гэвэл тэгшитгэх урсгалыг тооцоол."}, {"t": "p", "s": "3. Жишээ 6.6-ийн Zbus давталтыг Python-д програмчилж, A–1 салаа тасарсан горимын хүчдэлийг гарга (Хүснэгт 6.3-тай тулга).", "h": "3. Жишээ 6.6-ийн <b>Z</b><sub>bus</sub> давталтыг Python-д програмчилж, A–1 салаа тасарсан горимын хүчдэлийг гарга (Хүснэгт 6.3-тай тулга)."}, {"t": "h", "l": 1, "s": "Ашигласан ном", "h": "<b>Ашигласан ном</b>"}, {"t": "p", "s": "1. Ш.Гантөмөр. Цахилгаан шугам сүлжээ, систем. — УБ.: Соёмбопринтинг, 2017.", "h": "1. Ш.Гантөмөр. Цахилгаан шугам сүлжээ, систем. — УБ.: Соёмбопринтинг, 2017."}, {"t": "p", "s": "2. Ш.Гантөмөр. ЦШС-ний. Цахилгаан шугам сүлжээ. — УБ.: Соёмбопринтинг, 2003.", "h": "2. Ш.Гантөмөр. ЦШС-ний. Цахилгаан шугам сүлжээ. — УБ.: Соёмбопринтинг, 2003."}, {"t": "p", "s": "3. Glover J.D., Overbye T., Sarma M. Power SystemAnalysis and Design. — Cengage, 2017.", "h": "3. Glover J.D., Overbye T., Sarma M. Power SystemAnalysis and Design. — Cengage, 2017."}, {"t": "p", "s": "4. Идельчик В.И. Электрические системы и сети. — М.: Энергоатомиздат, 1989.", "h": "4. Идельчик В.И. Электрические системы и сети. — М.: Энергоатомиздат, 1989."}];